ON CONFLICT (role_slug) DO UPDATE SET
    role_name = EXCLUDED.role_name,
    min_salary = EXCLUDED.min_salary,
    max_salary = EXCLUDED.max_salary,
    avg_salary = EXCLUDED.avg_salary,
    sample_size = EXCLUDED.sample_size,
    updated_at = NOW();

-- Populate job_roles table from salary_guides
INSERT INTO job_roles (slug, name, industry_id, seo_title, seo_description)
SELECT role_slug, role_name, (SELECT id FROM industries WHERE slug = 'technology' LIMIT 1), seo_title, seo_description
FROM salary_guides
ON CONFLICT (slug) DO NOTHING;
